#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) {
    malloc_reset();
}

void unit_test_shrink_array_malloc_failure(void) {
    DArrayStack *stack = create_stack(2);
    TEST_ASSERT_NOT_NULL(stack);
    int push_result = push(stack, 42);
    TEST_ASSERT_EQUAL_INT(0, push_result);

    malloc_fail_after(2);

    DArrayStack *result = shrink_array(stack, 2);
    TEST_ASSERT_NULL(result);
    TEST_ASSERT_NOT_NULL(stack);
    TEST_ASSERT_NOT_NULL(stack->arrPtr);
    TEST_ASSERT_EQUAL_INT(2, stack->capacity);
    TEST_ASSERT_EQUAL_INT(0, stack->top);

    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_shrink_array_malloc_failure);
    return UNITY_END();
}

